{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Phytoene, the closest structural analogue (a C40 polyisoprenoid hydrocarbon), showed 58.5% absolute oral bioavailability in humans, indicating that some highly lipophilic isoprenoids can be well absorbed.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C09"],
      "claim": "Lycopene, a structurally related C40 polyisoprenoid, showed only 0.17% systemic availability after oral intake in humans, supporting low oral bioavailability for large lipophilic isoprenoids.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "A 13C-labeled lycopene study in healthy adults estimated all-trans lycopene bioavailability at 23.2%, above the 20% threshold, showing that some high estimates exist but are method- and formulation-dependent.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C13"],
      "claim": "Tocotrienol-rich palm oil, containing a chromanol head with an isoprenoid tail, has poor oral bioavailability, directly supporting low F for amphipathic isoprenoid lipids similar to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Hyperforin, a prenylated lipophilic natural product, showed high oral bioavailability, indicating that prenylation and lipophilicity alone do not preclude high F, though its smaller size and different polar groups limit transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C07"],
      "claim": "Mycophenolate mofetil, a small ester prodrug, showed almost complete oral bioavailability (~94%), but this is weakly transferable to the large, non-prodrug quinone query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C25"],
      "claim": "BI 425809, a small synthetic drug, had 71.6% absolute oral bioavailability in humans, but its low structural similarity to the query limits its relevance.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C10"],
      "claim": "Nabumetone showed 32% systemic bioavailability in cirrhotic patients, but low structural similarity and the disease condition limit transferability to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C12"],
      "claim": "Mulberroside A showed low oral bioavailability in humans due to bacterial deglycosylation; this is supportive of low F but the glycoside prodrug mechanism is not transferable to the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a large, highly lipophilic ubiquinone/polyprenyl quinone (CoQ10-like) with very high logP, high molecular weight, and no ionizable groups. The most relevant experimental analogues—lycopene and tocotrienol—show poor oral bioavailability, and the physicochemical liabilities strongly support F < 20%. Although phytoene and some labeled lycopene estimates exceed 20%, their transferability is limited by structural differences, formulation effects, and assay variability. Overall, low oral bioavailability is better supported.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query molecule itself.",
    "Lycopene bioavailability estimates vary widely by method, formulation, and isomer, creating uncertainty in the direction and magnitude of transfer.",
    "Tocotrienol evidence comes from a complex fraction rather than a pure compound.",
    "Phytoene's high bioavailability may not transfer because the query contains a polar quinone head and much higher molecular weight."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

